296	ASCENDC_EXTERN_C ge::graphStatus TilingPrepareForFlashAttentionScoreGradEnhance(gert::TilingParseContext *context)
297	{
298	    OP_CHECK_IF(context == nullptr, OP_LOGE("TilingPrepare", "context is null."), return ge::GRAPH_FAILED);
299	    fe::PlatFormInfos *platformInfoPtr = context->GetPlatformInfo();
300	    OP_CHECK_IF(platformInfoPtr == nullptr, OP_LOGE(context, "platformInfoPtr is null."), return ge::GRAPH_FAILED);
301	
302	    auto compileInfoPtr = context->GetCompiledInfo<FlashAttentionScoreGradEnhanceCompileInfo>();
303	    OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context, "compileInfoPtr is null."), return ge::GRAPH_FAILED);
304	
305	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
306	    compileInfoPtr->aivNum = ascendcPlatform.GetCoreNumAiv();
307	    compileInfoPtr->aicNum = ascendcPlatform.GetCoreNumAic();
308	    compileInfoPtr->socVersion = ascendcPlatform.GetSocVersion();
309	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
310	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, compileInfoPtr->l1Size);
311	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, compileInfoPtr->l0aSize);
312	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_B, compileInfoPtr->l0bSize);
313	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, compileInfoPtr->l0cSize);
314	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L2, compileInfoPtr->l2CacheSize);
315	
316	    OP_LOGI(context,
317	            "parse TilingParseContext succ. aivNum:%u, aicNum:%u, "
318	            "ubSize:%lu, l1Size:%lu, l0aSize:%lu, l0bSize:%lu, l0cSize:%lu, l2CacheSize:%lu",
319	            compileInfoPtr->aivNum,
320	            compileInfoPtr->aicNum,
321	            compileInfoPtr->ubSize,
322	            compileInfoPtr->l1Size,
323	            compileInfoPtr->l0aSize,
324	            compileInfoPtr->l0bSize,
325	            compileInfoPtr->l0cSize,
326	            compileInfoPtr->l2CacheSize);
327	
328	    return ge::GRAPH_SUCCESS;
329	}
