186	    auto queryShapeDim = queryShape->GetStorageShape().GetDimNum();
187	    if (attentionInShapeDim != queryShapeDim) {
188	        OP_LOGE(
189	            context, "The dimnum of attentionIn %zu should be equal to query %zu", attentionInShapeDim, queryShapeDim);
