191	    }
192	    for (size_t i = 0; i < queryShapeDim; i++) {
193	        // No matter TND, SBH, BSH, BSND, BNSD, the last dim could be different
194	        if (i == queryShapeDim - 1) {
195	            continue;
196	        } else if (attentionInShape->GetStorageShape().GetDim(i) != queryShape->GetStorageShape().GetDim(i)) {
197	            OP_LOGE(context,
198	                    "The dim %zu of attentionIn shape is invalid, got %ld, should be %ld",
199	                    i,
200	                    attentionInShape->GetStorageShape().GetDim(i),
201	                    queryShape->GetStorageShape().GetDim(i));
202	            return ge::GRAPH_FAILED;
203	        }
204	    }
205	
206	    return ge::GRAPH_SUCCESS;
