246	ge::graphStatus CheckShapeValid(gert::TilingContext *context, int64_t b, int64_t n1, int64_t s1, int64_t d)
247	{
248	    auto isShapeInValid = (b == 0 || n1 == 0 || s1 == 0 || d == 0);
249	    OP_CHECK_IF(isShapeInValid,
250	                OP_LOGE(context, "input shape error, got 0 in bnsd(%ld,%ld,%ld,%ld)", b, n1, s1, d),
251	                return ge::GRAPH_FAILED);
252	
253	    auto ret = CheckSoftmaxMaxShape(context, b, n1, s1);
254	    if (ret != ge::GRAPH_SUCCESS) {
255	        return ret;
