76	    int64_t n2;
77	    int64_t g;
78	    int64_t actualS1Len;
79	    int64_t actualS2Len;
80	
81	    bool tndSoftmaxIn;
82	    float scaleValue;
83	
84	    int32_t cubeBaseMN;
85	
86	    int32_t s1VecSize;
87	    int32_t s2VecSize;
88	    constexpr static int32_t BASE_BLOCK_LENGTH = 128;
89	    constexpr static int32_t S1_CUBESIZE = BASE_BLOCK_LENGTH;
90	    constexpr static int32_t S2_CUBESIZE = BASE_BLOCK_LENGTH;
91	
92	    int32_t s1Extend;
93	    int32_t s2Extend;
94	    int32_t s2ExtendAlign;
95	    int32_t s1CubeExtend;
96	    int32_t s2CubeExtend;
97	
98	    int32_t curS1Idx;
99	    int32_t curS2Idx;
100	
101	    // offset
102	    int32_t sfmgOffset = 0;
103	    int32_t softMaxOffset = 0;
104	
105	    int64_t copyInOffset = 0;
106	    int64_t copyOutOffset = 0;
107	    DataCopyParams copyInParam;
108	    DataCopyParams copyOutParam;
109	
110	    int64_t batch;
111	    int64_t headNum;
112	    int64_t headDim;
113	    int64_t coreNum;
114	    int64_t mixCoreNum;
115	    struct CubeAddrInfo cubeAddrInfo[2];
116	    struct VecAddrInfo vecAddrInfo;
117	    GM_ADDR actual_seq_qlen_addr;
118	    GM_ADDR actual_seq_kvlen_addr;
119	    const TILING_TYPE *__restrict tilingData;
120	
121	private:
122	    __aicore__ inline void GetSeqQlenKvlenByBidx(int64_t bIdx, int64_t &actualSeqQlen, int64_t &actualSeqKvlen);
123	    __aicore__ inline void CopyInAttenMaskBool(LocalTensor<uint8_t> &dstTensor, int64_t attenMaskOffset,
124	                                               uint32_t s1Extend, uint32_t s2Extend);
125	    __aicore__ inline void CalcAttenMaskBool(LocalTensor<float> &dstTensor, LocalTensor<uint8_t> srcTensor,
126	                                             uint32_t s1Extend, uint32_t s2SrcExtend,
127	                                             uint32_t s2MaskExtend = BASE_BLOCK_LENGTH, uint8_t maskType = 0);
128	    __aicore__ inline void CopyInSoftMax(LocalTensor<float> &dstTensor, uint32_t s1Extend, uint32_t softMaxOffset);
129	    __aicore__ inline void CalcSoftMax(LocalTensor<float> &dstTensor, LocalTensor<float> &src0Tensor,
130	                                       LocalTensor<float> &src1Tensor, uint32_t s1Extend, uint32_t s2Extend,
131	                                       uint32_t s2ExtendAlign, const SoftMaxTiling &tiling);
132	    __aicore__ inline void SubGrapA(int64_t curIdx, const VecBlockInfo &blockInfo, event_t mte2WaitMte3A);
133	    __aicore__ inline void SubGrapB(int64_t curIdx, const VecBlockInfo &blockInfo, event_t mte2WaitMte3B);
134	};
