244	CubeOp<TYPE>::Init(TPipe *pipe, uint64_t qHeadNumIn, uint64_t kvHeadNumIn, uint64_t headDimIn, uint64_t sparseMode)
245	{
246	    pipe->InitBuffer(L1Buffer, HardwareInfo<ArchType::ASCEND_V220>::l1Size);
247	    pipe->InitBuffer(L0CBuffer, HardwareInfo<ArchType::ASCEND_V220>::l0CSize);
248	
249	    qHeadNum = qHeadNumIn;
250	    kvHeadNum = kvHeadNumIn;
251	    headDim = headDimIn;
252	    sparseType = sparseMode;
253	    globalBlockOffset = GetBlockIdx() * 16 * 128 * 128;
254	
255	    temp_tensor_bf16.SetGlobalBuffer(reinterpret_cast<__gm__ TYPE *>(0));
256	    temp_tensor_fp32.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(0));
257	
258	    AscendC::SetLoadDataPaddingValue<uint64_t>(0);
259	    AscendC::SetNdParaImpl(0x1);
260	
261	    // init L1 tensor
262	    l1_a_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(0);
263	    l1_a_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(SIZE_128 * SIZE_ONE_K);
264	    l1_b_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(SIZE_256 * SIZE_ONE_K);
265	    l1_b_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(SIZE_384 * SIZE_ONE_K);
266	    // init L0A/L0B/L0C tensor
267	    l0_a_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0A, TYPE>(0);
268	    l0_a_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0A, TYPE>(SIZE_32 * SIZE_ONE_K);
269	    l0_b_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0B, TYPE>(0);
270	    l0_b_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0B, TYPE>(SIZE_32 * SIZE_ONE_K);
271	    l0_c_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0C, float>(0);
272	    l0_c_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0C, float>(SIZE_64 * SIZE_ONE_K);
273	
274	    // init 64 extra l1_b_buf_tensor
275	    l1_b1_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(SIZE_256 * SIZE_ONE_K);
276	    l1_b1_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(SIZE_320 * SIZE_ONE_K);
277	    l1_b2_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(SIZE_384 * SIZE_ONE_K);
278	    l1_b2_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_CB, TYPE>(SIZE_448 * SIZE_ONE_K);
279	
280	    // init 64 L0C tensor
281	    l0_c1_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0C, float>(0);
282	    l0_c1_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0C, float>(SIZE_32 * SIZE_ONE_K);
283	    l0_c2_ping_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0C, float>(SIZE_64 * SIZE_ONE_K);
284	    l0_c2_pong_tensor = asdopsBuf.GetBuffer<BufferType::ASCEND_L0C, float>(SIZE_96 * SIZE_ONE_K);
285	
286	    commonFixpipeParamsV220.quantPre = QuantMode_t::NoQuant;
287	    commonFixpipeParamsV220.unitFlag = 3;
288	}
