290	template <typename TYPE>
291	__aicore__ inline __attribute__((always_inline)) void
292	CubeOp<TYPE>::Cube1Process(const CubeAddrInfo &addrs, __gm__ TYPE *left, __gm__ TYPE *right, __gm__ float *out)
293	{
294	    pingPongIdx = addrs.taskId % 2;
295	    globalBlockOffset = GetBlockIdx() * BLOCK_WORKSPACE * 2 + pingPongIdx * BLOCK_WORKSPACE;
296	
297	    for (uint32_t i = 0; i < addrs.blockLength; ++i) {
298	        Cube1Compute(addrs.addrInfo[i], left, right, out);
299	    }
300	}
