304	CubeOp<TYPE>::Cube2Process(const CubeAddrInfo &addrs, __gm__ TYPE *left, __gm__ TYPE *right, __gm__ float *out)
305	{
306	    pingPongIdx = addrs.taskId % 2;
307	    globalBlockOffset = GetBlockIdx() * BLOCK_WORKSPACE * 2 + pingPongIdx * BLOCK_WORKSPACE;
308	
309	    for (uint32_t i = 0; i < addrs.blockLength; ++i) {
310	        Cube2Compute(addrs.addrInfo[i], left, right, out, i == 0);
311	    }
312	}
