16	#ifndef FLASH_ATTENTION_SCORE_GRAD_ENHANCE_SFMG_KERNEL_H_
17	#define FLASH_ATTENTION_SCORE_GRAD_ENHANCE_SFMG_KERNEL_H_
18	
19	#include "kernel_operator.h"
20	
21	template <typename T1, typename T2, typename TILING_TYPE, const uint32_t INPUT_LAYOUT>
22	class FlashAttentionScoreGradEnhanceSfmg {
23	  public:
24	    __aicore__ inline FlashAttentionScoreGradEnhanceSfmg(){};
25	    __aicore__ inline void Init(__gm__ uint8_t *dy,
26	                                __gm__ uint8_t *attenIn,
27	                                __gm__ uint8_t *actual_seq_qlen,
28	                                __gm__ uint8_t *dq,
29	                                __gm__ uint8_t *dk,
30	                                __gm__ uint8_t *dv,
31	                                __gm__ uint8_t *drop_mask,
32	                                __gm__ uint8_t *workspace,
33	                                const TILING_TYPE *ordTilingData,
34	                                TPipe *pipe_in);
35	    __aicore__ inline void Process();
36	    __aicore__ inline void SyncALLCores();
37	    __aicore__ inline void InitIndex(int64_t startIdx, int64_t &curS, GM_ADDR seqS);
38	    __aicore__ inline void CopyInSfmg(int64_t leftNburst, int64_t &curS, GM_ADDR seqS);
39	    __aicore__ inline void DoCopyIn(int64_t curS, int64_t curNBurst, int64_t dstOffset, GM_ADDR seqS);
40	
41	  protected:
42	    constexpr static uint32_t BNGSD = 0;
43	    constexpr static uint32_t SBNGD = 1;
44	    constexpr static uint32_t BSNGD = 2;
45	    constexpr static uint32_t TND = 3;
46	    constexpr static int64_t BLOCK_BYTE_SIZE = 32;
47	    constexpr static int64_t BLOCK_SIZE = 8;
48	    constexpr static int64_t SFMG_HIGH_PERF_N_FACTOR = 8;
49	    constexpr static int64_t SFMG_HIGH_PERF_D_FACTOR = 64;
50	
51	    TPipe *pipe;
52	    uint32_t cBlockIdx;
53	
54	    const TILING_TYPE *TilingData;
55	
56	    GlobalTensor<T2> sfmgWorkspaceGm;
57	    GlobalTensor<T1> dyGm;
58	    GlobalTensor<T1> attenInGm;
59	    TQue<QuePosition::VECIN, 1> input1Que, input2Que;
60	    TBuf<> cast1Buf, cast2Buf, tmpBuf;
61	    TQue<QuePosition::VECOUT, 1> out1Que;
62	
63	    int64_t b;
64	    int64_t n1;
65	    int64_t s1;
66	    int64_t s2;
67	    int64_t d;
68	    int64_t dAlign;
69	    GM_ADDR actual_seq_qlen_addr;
70	
71	    int64_t bIdx = 0;
72	    int64_t nIdx = 0;
73	    int64_t sIdx = 0;
74	
75	    int64_t dstOffset = 0;
76	    int64_t transpse_stride = 0;
77	
78	    LocalTensor<T1> input1Buf;
79	    LocalTensor<T1> input2Buf;
80	    LocalTensor<T2> outputBuf;
81	};
82	
83	template <typename T1, typename T2, typename TILING_TYPE, const uint32_t INPUT_LAYOUT>
84	__aicore__ inline void
85	FlashAttentionScoreGradEnhanceSfmg<T1, T2, TILING_TYPE, INPUT_LAYOUT>::Init(__gm__ uint8_t *dy,
86	                                                                            __gm__ uint8_t *attenIn,
87	                                                                            __gm__ uint8_t *actual_seq_qlen,
88	                                                                            __gm__ uint8_t *dq,
89	                                                                            __gm__ uint8_t *dk,
90	                                                                            __gm__ uint8_t *dv,
91	                                                                            __gm__ uint8_t *drop_mask,
92	                                                                            __gm__ uint8_t *workspace,
93	                                                                            const TILING_TYPE *orgTilingData,
94	                                                                            TPipe *pipe_in)
95	{
96	    cBlockIdx = GetBlockIdx();
97	    TilingData = orgTilingData;
98	    pipe = pipe_in;
99	    dyGm.SetGlobalBuffer((__gm__ T1 *)dy);
100	    attenInGm.SetGlobalBuffer((__gm__ T1 *)attenIn);
101	    sfmgWorkspaceGm.SetGlobalBuffer((__gm__ T2 *)workspace +
102	                                    TilingData->preSfmgTilingData.sfmgPreBeginAddr / sizeof(T2));
103	
104	    pipe->InitBuffer(input1Que, 1, TilingData->preSfmgTilingData.inputBufferLen); // 24K
105	    pipe->InitBuffer(input2Que, 1, TilingData->preSfmgTilingData.inputBufferLen); // 24K
106	    pipe->InitBuffer(cast1Buf, TilingData->preSfmgTilingData.castBufferLen); // 48K
107	    pipe->InitBuffer(cast2Buf, TilingData->preSfmgTilingData.castBufferLen); // 48K
108	    pipe->InitBuffer(out1Que, 1, TilingData->preSfmgTilingData.outputBufferLen);
109	    pipe->InitBuffer(tmpBuf, TilingData->preSfmgTilingData.tempBufferLen); // 40K - outputBufferLen
110	
111	    b = TilingData->preSfmgTilingData.b;
112	    n1 = TilingData->preSfmgTilingData.n2 * TilingData->preSfmgTilingData.g;
113	    s1 = TilingData->preSfmgTilingData.s1;
114	    d = TilingData->preSfmgTilingData.value_d;
115	    int64_t blockNums = BLOCK_BYTE_SIZE / sizeof(T1);
116	    dAlign = (d + blockNums - 1) / blockNums * blockNums;
117	    actual_seq_qlen_addr = actual_seq_qlen;
118	
119	    if constexpr (INPUT_LAYOUT == TND) {
120	        transpse_stride = (n1 * d - d) * sizeof(T1);
121	    } else if constexpr (INPUT_LAYOUT == BNGSD) {
122	        transpse_stride = 0;
123	    } else if constexpr (INPUT_LAYOUT == BSNGD) {
124	        transpse_stride = (n1 * d - d) * sizeof(T1);
125	    } else if constexpr (INPUT_LAYOUT == SBNGD) {
126	        transpse_stride = (b * n1 * d - d) * sizeof(T1);
127	    }
128	}
129	
130	template <typename T1, typename T2, typename TILING_TYPE, const uint32_t INPUT_LAYOUT>
131	__aicore__ inline void FlashAttentionScoreGradEnhanceSfmg<T1, T2, TILING_TYPE, INPUT_LAYOUT>::InitIndex(
132	    int64_t startIdx, int64_t &curS, GM_ADDR seqS)
133	{
134	    if constexpr (INPUT_LAYOUT == TND) {
135	        int64_t totalLen = 0;
136	        for (int64_t bDimIdx = bIdx; bDimIdx < b; bDimIdx++) {
137	            totalLen = n1 * ((__gm__ int64_t *)seqS)[bDimIdx] * d;
138	            if (totalLen > startIdx) {
139	                bIdx = bDimIdx;
140	                curS = (bIdx == 0) ? ((__gm__ int64_t *)seqS)[bIdx]
141	                                   : (((__gm__ int64_t *)seqS)[bIdx] - ((__gm__ int64_t *)seqS)[bIdx - 1]);
142	                int64_t bTail = startIdx - (totalLen - n1 * curS * d);
143	                nIdx = bTail / (curS * d);
144	                int64_t nTail = bTail % (curS * d);
145	                sIdx = nTail / d;
146	                break;
147	            }
148	        }
149	    } else {
150	        bIdx = startIdx / (n1 * s1 * d);
151	        int64_t bTail = startIdx % (n1 * s1 * d);
152	        nIdx = bTail / (s1 * d);
153	        int64_t nTail = bTail % (s1 * d);
154	        sIdx = nTail / d;
155	    }
156	}
157	
158	template <typename T1, typename T2, typename TILING_TYPE, const uint32_t INPUT_LAYOUT>
159	__aicore__ inline void FlashAttentionScoreGradEnhanceSfmg<T1, T2, TILING_TYPE, INPUT_LAYOUT>::DoCopyIn(
160	    int64_t curS, int64_t curNBurst, int64_t dstOffset, GM_ADDR seqS)
161	{
162	    int64_t srcOffset = 0;
163	    if constexpr (INPUT_LAYOUT == TND) {
164	        int64_t bOffset = bIdx == 0 ? 0 : n1 * ((__gm__ int64_t *)seqS)[bIdx - 1] * d;
165	        srcOffset = bOffset + (sIdx * n1 + nIdx) * d;
166	    } else {
167	        if constexpr (INPUT_LAYOUT == BNGSD) {
168	            srcOffset = bIdx * (n1 * s1 * d) + nIdx * (s1 * d) + sIdx * d;
169	        } else if constexpr (INPUT_LAYOUT == BSNGD) {
170	            srcOffset = bIdx * (s1 * n1 * d) + sIdx * (n1 * d) + nIdx * d;
171	        } else if constexpr (INPUT_LAYOUT == SBNGD) {
172	            srcOffset = sIdx * (b * n1 * d) + bIdx * (n1 * d) + nIdx * d;
173	        }
174	    }
175	
176	    DataCopyPad(input1Buf[dstOffset],
177	                dyGm[srcOffset],
178	                {static_cast<uint16_t>(curNBurst),
179	                 static_cast<uint32_t>(d * sizeof(T1)),
180	                 static_cast<uint32_t>(transpse_stride),
181	                 0,
182	                 0},
183	                {true, 0, static_cast<uint8_t>((dAlign - d)), 0});
184	    DataCopyPad(input2Buf[dstOffset],
185	                attenInGm[srcOffset],
186	                {static_cast<uint16_t>(curNBurst),
187	                 static_cast<uint32_t>(d * sizeof(T1)),
188	                 static_cast<uint32_t>(transpse_stride),
189	                 0,
190	                 0},
191	                {true, 0, static_cast<uint8_t>((dAlign - d)), 0});
192	}
193	
194	template <typename T1, typename T2, typename TILING_TYPE, const uint32_t INPUT_LAYOUT>
195	__aicore__ inline void FlashAttentionScoreGradEnhanceSfmg<T1, T2, TILING_TYPE, INPUT_LAYOUT>::CopyInSfmg(
196	    int64_t leftNburst, int64_t &curS, GM_ADDR seqS)
197	{
198	    int64_t dstOffset = 0;
199	    while (leftNburst > 0) {
200	        int64_t curNburst = 0;
201	        if (curS - sIdx < leftNburst) { // 需要借N或借B
202	            curNburst = curS - sIdx;
203	            DoCopyIn(curS, curNburst, dstOffset, seqS);
204	            leftNburst = leftNburst - curNburst;
205	            sIdx = 0;
206	            if (nIdx < n1 - 1) { // 需要借N
207	                nIdx += 1;
208	            } else {
209	                nIdx = 0;
210	                if (bIdx < b - 1) { // 需要借B
211	                    bIdx += 1;
212	                    if constexpr (INPUT_LAYOUT == TND) {
213	                        curS = ((__gm__ int64_t *)seqS)[bIdx] - ((__gm__ int64_t *)seqS)[bIdx - 1];
214	                    } else {
215	                        curS = s1;
216	                    }
217	                } else { // 没有轴可以借了，end
218	                    leftNburst = 0;
219	                }
220	            }
221	        } else { // 当前S够用
222	            curNburst = leftNburst;
223	            DoCopyIn(curS, curNburst, dstOffset, seqS);
224	            sIdx = sIdx + leftNburst;
225	            leftNburst = 0;
226	        }
227	        dstOffset = dstOffset + curNburst * dAlign;
228	    }
229	}
230	
231	template <typename T1, typename T2, typename TILING_TYPE, const uint32_t INPUT_LAYOUT>
232	__aicore__ inline void FlashAttentionScoreGradEnhanceSfmg<T1, T2, TILING_TYPE, INPUT_LAYOUT>::Process()
233	{
234	    AscendC::PipeBarrier<PIPE_ALL>(); // 去掉pre和sfmg之间的SyncALL，这里需要增加pipeALL
235	
236	    uint32_t usedCoreNums = TilingData->preSfmgTilingData.usedCoreNum;
237	    if (cBlockIdx < usedCoreNums) {
238	        LocalTensor<uint8_t> tempBuf = tmpBuf.Get<uint8_t>();
239	        LocalTensor<T2> sfmgClc1 = cast1Buf.Get<T2>();
240	        LocalTensor<T2> sfmgClc2 = cast2Buf.Get<T2>();
241	
242	        int64_t singleCoreLoopTimes = TilingData->preSfmgTilingData.normalCoreLoopTimes;
243	        int64_t singleCoreLastLoopNBurstNum =
244	            TilingData->preSfmgTilingData.normalCoreLastLoopNBurstNum; // 普通单核最后一次loop处理多少个D
245	        if (cBlockIdx == usedCoreNums - 1) {
246	            singleCoreLoopTimes = TilingData->preSfmgTilingData.tailCoreLoopTimes;
247	            singleCoreLastLoopNBurstNum = TilingData->preSfmgTilingData.tailCoreLastLoopNBurstNum;
248	        }
249	
250	        int64_t startIdx = cBlockIdx * TilingData->preSfmgTilingData.normalCoreNBurstNums;
251	        int64_t nBurst = TilingData->preSfmgTilingData.singleLoopNBurstNum;
252	        int64_t curS = s1;
253	
254	        for (int64_t i = 0; i < singleCoreLoopTimes; i++) {
255	            if (i == singleCoreLoopTimes - 1) {
256	                nBurst = singleCoreLastLoopNBurstNum;
257	            }
258	
259	            // copyIn
260	            if (i == 0) {
261	                input1Buf = input1Que.AllocTensor<T1>();
262	                input2Buf = input2Que.AllocTensor<T1>();
263	                InitIndex(
264	                    (startIdx + i * TilingData->preSfmgTilingData.singleLoopNBurstNum) * d, curS, actual_seq_qlen_addr);
265	                CopyInSfmg(nBurst, curS, actual_seq_qlen_addr);
266	            }
267	
268	            // cast 1
269	            input1Que.EnQue(input1Buf);
270	            input1Que.DeQue<T1>();
271	            int64_t calcSize = nBurst * dAlign;
272	            Cast(sfmgClc1, input1Buf, RoundMode::CAST_NONE, calcSize);
273	            AscendC::PipeBarrier<PIPE_V>();
274	            input1Que.FreeTensor(input1Buf);
275	
276	            // cast 2
277	            input2Que.EnQue(input2Buf);
278	            input2Que.DeQue<T1>();
279	            Cast(sfmgClc2, input2Buf, RoundMode::CAST_NONE, calcSize);
280	            AscendC::PipeBarrier<PIPE_V>();
281	            input2Que.FreeTensor(input2Buf);
282	
283	            // pre copyIn next nBurst
284	            if (i < singleCoreLoopTimes - 1) {
285	                int64_t nextNBurst = i == singleCoreLoopTimes - 2 ? singleCoreLastLoopNBurstNum : nBurst;
286	                input1Buf = input1Que.AllocTensor<T1>();
287	                input2Buf = input2Que.AllocTensor<T1>();
288	                InitIndex((startIdx + (i + 1) * TilingData->preSfmgTilingData.singleLoopNBurstNum) * d,
289	                          curS,
290	                          actual_seq_qlen_addr);
291	                CopyInSfmg(nextNBurst, curS, actual_seq_qlen_addr);
292	            }
293	
294	            // sfmg
295	            outputBuf = out1Que.AllocTensor<T2>();
296	            Duplicate<T2>(outputBuf, 0.0, nBurst * 8);
297	            AscendC::PipeBarrier<PIPE_V>();
298	
299	            uint32_t shapeArray[] = {static_cast<uint32_t>(nBurst), static_cast<uint32_t>(dAlign)};
300	            sfmgClc1.SetShapeInfo(ShapeInfo(2, shapeArray, DataFormat::ND));
301	            sfmgClc2.SetShapeInfo(ShapeInfo(2, shapeArray, DataFormat::ND));
302	            uint32_t shapeArray1[] = {static_cast<uint32_t>(nBurst), BLOCK_BYTE_SIZE / sizeof(T2)};
303	            outputBuf.SetShapeInfo(ShapeInfo(2, shapeArray1, DataFormat::ND));
304	
305	            bool isBasicBlock = (nBurst % SFMG_HIGH_PERF_N_FACTOR == 0) && (dAlign % SFMG_HIGH_PERF_D_FACTOR == 0);
306	            if (likely(isBasicBlock)) {
307	                SoftmaxGradFront<float, true>(
308	                    outputBuf, sfmgClc1, sfmgClc2, tempBuf, TilingData->softmaxGradTilingData);
309	            } else {
310	                SoftmaxGradFront<float, false>(
311	                    outputBuf, sfmgClc1, sfmgClc2, tempBuf, TilingData->softmaxGradTilingData);
312	            }
313	            AscendC::PipeBarrier<PIPE_V>();
314	
315	            // copyOut
316	            out1Que.EnQue(outputBuf);
317	            out1Que.DeQue<T2>();
318	            int64_t sfmgOutputOffset = (startIdx + i * TilingData->preSfmgTilingData.singleLoopNBurstNum) * BLOCK_SIZE;
319	            DataCopy(sfmgWorkspaceGm[sfmgOutputOffset], outputBuf, nBurst * BLOCK_SIZE);
320	            out1Que.FreeTensor(outputBuf);
321	        }
322	    }
