};

template <typename T1, typename T2, typename TILING_TYPE, const uint32_t INPUT_LAYOUT>
__aicore__ inline void
FlashAttentionScoreGradEnhanceSfmg<T1, T2, TILING_TYPE, INPUT_LAYOUT>::Init(__gm__ uint8_t *dy,
                                                                            __gm__ uint8_t *attenIn,
                                                                            __gm__ uint8_t *actual_seq_qlen,
                                                                            __gm__ uint8_t *dq,
                                                                            __gm__ uint8_t *dk,
                                                                            __gm__ uint8_t *dv,
                                                                            __gm__ uint8_t *drop_mask,
                                                                            __gm__ uint8_t *workspace,
                                                                            const TILING_TYPE *orgTilingData,
                                                                            TPipe *pipe_in)
